-- evt:thing:fountain_ability
RegisterEvent(76, "Fountain of Ability", function()
    if not (not (IsAtLeast(MapVar(2), 1))) then
        evt.StatusText("The fountain has run dry for you.", 4)
        return
    end
    SetValue(MapVar(2), 1)
    AddValue(BaseLuck, 2)
    evt.StatusText("+2 Luck (permanent)")
end, "Fountain of Ability")

-- evt:thing:waters_of_power
RegisterEvent(77, "Waters of Power", function()
    AddValue(HP, 25)
    evt.StatusText("+25 Hit points (temporary)")
end, "Waters of Power")

-- evt:thing:wishing_well
RegisterEvent(78, "Wishing Well", function()
    if not (IsAtLeast(Gold, 1)) then
        evt.StatusText("You have no coin to throw.")
        return
    end
    SubtractValue(Gold, 1)
    if math.random(1, 10) == 1 then evt.Add("Gold", 25) evt.StatusText("Your wish comes true: 25 gold glitters in the bucket.") else evt.StatusText("You make a wish.") end
end, "Wishing Well")

-- evt:thing:water_reflector
RegisterEvent(79, "Water Reflector", function(continueStep)
    local eventId = 79
    if continueStep == 1 then XeenQuests.hook("m37.reflector_water") return end
    if continueStep ~= nil then return end
    AskChoiceWithAnswerSteps(eventId, 3, "A disc of dark crystal on a stone stem, turned toward the stars below the rim. Reflector. Activate?", {{Answer = "Yes", Step = 1}, {Answer = "No", Step = 2}})
end, "Water Reflector")

