-- evt:thing:great_boulder
RegisterEvent(236, "A great boulder", function()
    if IsAtLeast(MapVar(6), 1) then return end
    if not (IsAtLeast(BaseMight, 15)) then
        evt.StatusText("The boulder does not budge (Might 15).", 4)
        return
    end
    SetValue(MapVar(6), 1)
    AddValue(Gold, 150)
    evt.StatusText("You heave the boulder over: a pouch of coins lies under it. +150 gold", 6)
end, "A great boulder")

